/* Clickable design prototype: mock events and mock currency, never real combat. */
const h = x => String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const title = x => x?.name?.[document.documentElement.lang==='en'?'en':'vi']||x?.name?.vi||x?.name||'';
const link = x => `?mock=1&scene=${x}`;
const nav = () => `<nav class="preview-navigation" aria-label="Màn mẫu">${['home','bot','lobby','match','result'].map(x=>`<a href="${link(x)}">${x}</a>`).join('')}</nav>`;
const header = (text,back='home') => `<header class="preview-header"><button data-action="go-${back}" aria-label="Quay lại">‹</button><h1>${text}</h1><button data-action="settings" aria-label="Cài đặt">⚙</button></header>`;
const footer = (action,text) => `<footer class="preview-footer"><button class="preview-primary" data-action="${action}">${text}</button></footer>`;
const character = (x,s) => `<button class="preview-character ${x.enabled?'':'locked'} ${x.id===s.characterId?'chosen':''}" data-action="${x.enabled?'select-character':'locked'}" data-id="${h(x.id)}" aria-disabled="${!x.enabled}"><img src="${h(x.assets.head)}" alt=""><b>${h(title(x))}</b><small>${x.enabled?(x.id===s.characterId?'ĐANG CHỌN':'CHỌN'):'🔒 SẮP RA MẮT'}</small></button>`;
const weapon = (x,s) => `<button class="preview-weapon ${x.enabled?'':'locked'} ${x.id===s.weaponId?'chosen':''}" data-action="${x.enabled?'select-weapon':'locked'}" data-id="${h(x.id)}" aria-disabled="${!x.enabled}"><img src="${h(x.icon)}" alt=""><span>${h(title(x))}</span><small>${x.enabled?(x.id===s.weaponId?'✓':'CHỌN'):'🔒'}</small></button>`;
function bot(s,c) {return `<main class="stage preview" data-screen="bot">${header('LUYỆN VỚI BOT')}<div class="preview-scroll"><h2>Chọn nhân vật</h2><div class="preview-roster">${c.characters.map(x=>character(x,s)).join('')}</div><h2>Chọn vũ khí</h2><div class="preview-weapons">${c.weapons.map(x=>weapon(x,s)).join('')}</div><div class="preview-count"><span>Số bot</span><button data-action="bot-minus">−</button><strong>${s.botCount}</strong><button data-action="bot-plus">+</button><small>${s.botCount+1} người gồm bạn</small></div>${s.build==='unity-prod'?'':'<p class="prototype-note">BẢN MẪU • Trận được mô phỏng</p>'}</div>${footer('start-practice','BẮT ĐẦU')}${s.build==='unity-prod'?'':nav()}</main>`}
function lobby(s,c){const me=c.characters.find(x=>x.id===s.characterId);return `<main class="stage preview" data-screen="lobby">${header(`PHÒNG ${h(s.lobby?.code||'HM4826')}`)}<div class="preview-scroll"><p>Phòng mẫu • 1/6 người</p><div class="preview-list"><div><img class="preview-small-head" src="${h(me?.assets.head)}" alt=""><span>Bạn · ${h(title(me))}</span><b>${s.lobbyReady?'SẴN SÀNG':'CHƯA SẴN SÀNG'}</b></div></div><p>Tất cả sẵn sàng thì trận tự bắt đầu.</p><button class="preview-secondary" data-action="lobby-practice">THỬ TRẬN MẪU VỚI BOT</button></div>${footer('lobby-ready',s.lobbyReady?'HỦY SẴN SÀNG':'SẴN SÀNG')}${nav()}</main>`}
function search(){return `<main class="stage preview" data-screen="search">${header('TÌM TRẬN')}<div class="preview-scroll"><h2>Đang tìm phòng mẫu…</h2><button class="preview-secondary" data-action="go-home">HỦY TÌM</button></div>${nav()}</main>`}
function match(s,c){const me=c.characters.find(x=>x.id===s.characterId),w=c.weapons.find(x=>x.id===s.weaponId),hp=s.mockHp??3;return `<main class="stage preview preview-match" data-screen="match"><div class="match-top"><div class="mock-match-summary"><b>VÒNG ${s.mockRound||1}/5</b><b data-name="mock-timer">${s.mockPhase==='placing'?`${Math.ceil(s.mockTimeLeft||0)} GIÂY`:h(s.mockPhase)}</b><button data-action="settings" aria-label="Cài đặt">⚙</button></div><div class="mock-player-row"><div class="mock-player-card"><img src="${h(me?.assets.head)}" alt=""><span>BẠN<br>${'♥'.repeat(hp)}${'♡'.repeat(3-hp)}</span></div><div class="mock-player-card secret">BOT 1<br>ẨN KHI NGẮM</div><button data-action="mock-ready">SẴN SÀNG</button></div></div><div class="match-arena"><img class="mock-hero" src="${h(me?.assets.portrait)}" alt="${h(title(me))}">${s.mockPhase!=='placing'?'<div class="mock-bot">BOT</div>':''}${s.mockPhase==='throwing'?`<img class="mock-projectile" src="${h(w?.icon)}" alt="Vũ khí đang bay">`:''}${s.mockEvent?`<div class="mock-event" role="status">${h(s.mockEvent)}</div>`:''}</div><div class="match-bottom"><button data-action="weapon">VŨ KHÍ: ${h(title(w))}</button><button data-action="emote">☺ BIỂU CẢM</button></div><span class="mock-label">TRẬN MẪU • KHÔNG TÍNH KẾT QUẢ</span>${nav()}</main>`}
function result(s,c){const me=c.characters.find(x=>x.id===s.characterId),names=[title(me),'Bot 1','Bot 2','Bot 3','Bot 4','Bot 5'].slice(0,s.botCount+1);return `<main class="stage preview" data-screen="result">${header('KẾT QUẢ TRẬN')}<div class="preview-scroll"><h2>CHIẾN THẮNG! (MẪU)</h2><p>Vòng ${s.mockRound||1}/5 • Trận mô phỏng</p><div class="preview-list">${names.map((n,i)=>`<div><span>${i+1}. ${h(n)}</span><b>${i?'ĐÃ LOẠI':'HẠNG 1'}</b></div>`).join('')}</div></div>${footer('go-home','VỀ TRANG CHỦ')}<button class="preview-replay" data-action="start-practice">CHƠI LẠI</button>${nav()}</main>`}
function settings(s){return `<main class="stage preview" data-screen="settings">${header('CÀI ĐẶT',s.previousScreen||'home')}<div class="preview-scroll"><label class="mock-setting">Nhạc nền <input type="range" data-setting="music" min="0" max="100" value="${Math.round(s.musicVolume*100)}"></label><label class="mock-setting">Hiệu ứng <input type="range" data-setting="sfx" min="0" max="100" value="${Math.round(s.sfxVolume*100)}"></label><button class="preview-secondary" data-action="settings-done">XONG</button></div>${nav()}</main>`}
function emote(){return `<main class="stage preview" data-screen="emote">${header('BIỂU CẢM','match')}<div class="preview-scroll"><h2>Sticker</h2><div class="mock-emoji-grid">${['😀','😂','😮','👍','💪','❤️'].map(x=>`<button data-action="send-emote" data-id="${x}">${x}</button>`).join('')}</div><h2>Câu nhanh</h2><button class="preview-secondary" data-action="send-emote" data-id="Chơi hay lắm!">Chơi hay lắm!</button></div>${nav()}</main>`}
function error(){return `<main class="stage preview" data-screen="error">${header('LỖI KẾT NỐI')}<div class="preview-scroll"><h2>Không thể vào phòng</h2></div>${footer('go-home','VỀ TRANG CHỦ')}${nav()}</main>`}
const pages={bot,lobby,search,match,result,settings,emote,error};
export function prototype(name,state,catalog){return (pages[name]||error)(state,catalog)}
